// eslint-disable-next-line @typescript-eslint/ban-ts-comment -- OpenNext가 build 단계에서 이 파일을 생성한다.
// @ts-ignore `.open-next/worker.js` is generated by the OpenNext build.
import * as generatedOpenNextWorker from "./.open-next/worker.js";
import type { AnyD1Database } from "drizzle-orm/d1";
import { createD1DbContext } from "./src/db/d1-context";
import {
  createScheduledMaintenanceOperations,
  runScheduledMaintenance,
  serializeScheduledMaintenanceReport,
  type ScheduledMaintenanceReport,
} from "./src/lib/scheduled-maintenance";
import {
  createR2BindingDeletionStorage,
  type RuntimeR2DeletionBucket,
} from "./src/lib/r2-deletion-storage";
import {
  enforceAccountCleanupStatusRateLimit,
  type AccountCleanupRateLimiter,
} from "./src/lib/account-cleanup-rate-limit";
import {
  reconcileManagedFinalMediaObjects,
  type RuntimeR2InventoryBucket,
} from "./src/lib/media-inventory-reconciliation";

type PortalWorkerEnv = {
  DB: AnyD1Database;
  BUCKET: RuntimeR2DeletionBucket & RuntimeR2InventoryBucket;
  ACCOUNT_CLEANUP_RATE_LIMITER: AccountCleanupRateLimiter;
};

type PortalExecutionContext = {
  waitUntil(promise: Promise<unknown>): void;
  passThroughOnException?(): void;
};

type ScheduledControllerInput = {
  cron: string;
  scheduledTime: number;
  type: "scheduled";
};

type OpenNextWorker = {
  fetch(
    request: Request,
    env: PortalWorkerEnv,
    context: PortalExecutionContext,
  ): Response | Promise<Response>;
};

const applicationWorker = generatedOpenNextWorker.default as OpenNextWorker;

export const BucketCachePurge = generatedOpenNextWorker.BucketCachePurge;
export const DOQueueHandler = generatedOpenNextWorker.DOQueueHandler;
export const DOShardedTagCache = generatedOpenNextWorker.DOShardedTagCache;

function logScheduledReport(report: ScheduledMaintenanceReport): void {
  const serialized = serializeScheduledMaintenanceReport(report);
  if (report.outcome === "partial_failure") {
    console.error(serialized);
  } else if (report.outcome === "ok") {
    console.log(serialized);
  } else {
    console.warn(serialized);
  }
}

async function runScheduledEvent(
  controller: ScheduledControllerInput,
  env: PortalWorkerEnv,
): Promise<void> {
  const context = createD1DbContext(env.DB);
  const storage = createR2BindingDeletionStorage(env.BUCKET);
  const report = await runScheduledMaintenance(
    createScheduledMaintenanceOperations(context, storage, (input) =>
      reconcileManagedFinalMediaObjects(context, env.BUCKET, input),
    ),
    {
      now: new Date(),
      scheduledAt: new Date(controller.scheduledTime),
    },
  );
  logScheduledReport(report);
  if (report.outcome === "partial_failure") {
    throw new Error("SCHEDULED_MAINTENANCE_FAILED");
  }
}

const portalWorker = {
  async fetch(
    request: Request,
    env: PortalWorkerEnv,
    context: PortalExecutionContext,
  ): Promise<Response> {
    const rateLimitResponse = await enforceAccountCleanupStatusRateLimit(
      request,
      env.ACCOUNT_CLEANUP_RATE_LIMITER,
    );
    if (rateLimitResponse) return rateLimitResponse;
    return applicationWorker.fetch(request, env, context);
  },
  async scheduled(
    controller: ScheduledControllerInput,
    env: PortalWorkerEnv,
    _context: PortalExecutionContext,
  ) {
    void _context;
    await runScheduledEvent(controller, env);
  },
};

export default portalWorker;
